class Solution {
public:
    int minArea(vector<vector<char>>& image, int x, int y) {
        int m = image.size(), n = image[0].size();
        auto searchRow = [&](int low, int high, bool check) {
            while (low < high) {
                int mid = (low + high) / 2;
                bool hasOne = false;
                for (int c = 0; c < n; c++) {
                    if (image[mid][c] == '1') { hasOne = true; break; }
                }
                if (hasOne == check) high = mid;
                else low = mid + 1;
            }
            return low;
        };
        auto searchCol = [&](int low, int high, bool check) {
            while (low < high) {
                int mid = (low + high) / 2;
                bool hasOne = false;
                for (int r = 0; r < m; r++) {
                    if (image[r][mid] == '1') { hasOne = true; break; }
                }
                if (hasOne == check) high = mid;
                else low = mid + 1;
            }
            return low;
        };
        int top = searchRow(0, x, true);
        int bottom = searchRow(x + 1, m, false);
        int left = searchCol(0, y, true);
        int right = searchCol(y + 1, n, false);
        return (bottom - top) * (right - left);
    }
};

class Solution {
    public int minArea(char[][] image, int x, int y) {
        int m = image.length, n = image[0].length;
        int top = searchRow(image, 0, x, true, n);
        int bottom = searchRow(image, x + 1, m, false, n);
        int left = searchCol(image, 0, y, true, m);
        int right = searchCol(image, y + 1, n, false, m);
        return (bottom - top) * (right - left);
    }
    private int searchRow(char[][] image, int low, int high, boolean check, int n) {
