var minArea = function(image, x, y) {
    const m = image.length, n = image[0].length;
    const searchRow = (low, high, check) => {
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            let hasOne = false;
            for (let c = 0; c < n; c++) {
                if (image[mid][c] === '1') { hasOne = true; break; }
            }
            if (hasOne === check) high = mid;
            else low = mid + 1;
        }
        return low;
    };
    const searchCol = (low, high, check) => {
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            let hasOne = false;
            for (let r = 0; r < m; r++) {
                if (image[r][mid] === '1') { hasOne = true; break; }
            }
            if (hasOne === check) high = mid;
            else low = mid + 1;
        }
        return low;
    };
    const top = searchRow(0, x, true);
    const bottom = searchRow(x + 1, m, false);
    const left = searchCol(0, y, true);
    const right = searchCol(y + 1, n, false);
    return (bottom - top) * (right - left);
};
